using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ForgeCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/ForgeCustomDescription", order = 0)]
public class ForgeCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ForgeAction forgeAction = battleAction as ForgeAction;
		string text = "";
		if (forgeAction.EnableExtraBattleAction)
		{
			text = "\n" + forgeAction.ExtraBattleAction.GetActionDescription(forgeAction.ExtraActionValue);
		}
		if (amountModified == EffectsValues.NO_VALUE_STRING)
		{
			return Smart.Format(GetRawLocalizedDescription(battleAction).Replace(" {1}", "").Replace("{1}", ""), forgeAction.ActionToTransmute.GetActionName()) + text;
		}
		return Smart.Format(GetRawLocalizedDescription(battleAction), forgeAction.ActionToTransmute.GetActionName(), GetAmountWithUnlockablesModification(amountModified)) + text;
	}

	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.CustomActionDescritionID);
	}
}
